package com.rpsbattle.tournament;
import com.rpsbattle.account.AccountAuthorizationService;
import com.rpsbattle.auth.AuthException;
import com.rpsbattle.online.DemoRequestException;
import com.rpsbattle.tournament.domain.*;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import java.util.*;

@Service public class TeamTournamentService {
 private final TournamentService tournaments;private final OwnedTournamentService owned;private final AccountAuthorizationService accounts;
 public TeamTournamentService(TournamentService tournaments,OwnedTournamentService owned,AccountAuthorizationService accounts){this.tournaments=tournaments;this.owned=owned;this.accounts=accounts;}
 @org.springframework.beans.factory.annotation.Autowired java.time.Clock clock=java.time.Clock.systemUTC();
 private static void require(boolean condition,String code){if(!condition)throw new DemoRequestException(code);}
 private void mutate(Authentication auth,String id,Long revision,java.util.function.BiConsumer<Tournament,UUID> action){var actor=accounts.requireUser(auth).id().value();var t=tournaments.find(id);synchronized(t){if(revision==null||revision!=t.revision)throw new AuthException("STALE_TOURNAMENT_REVISION",409);require(t.format==TournamentFormat.TEAM_ROUND_ROBIN,"INVALID_TOURNAMENT_FORMAT");owned.systemMutation(t,()->{action.accept(t,actor);tournaments.changed(t);});}}
 private static void rosterOpen(Tournament t){require(Set.of(TournamentStatus.DRAFT,TournamentStatus.REGISTRATION,TournamentStatus.CHECK_IN).contains(t.status),"TEAM_ROSTER_LOCKED");}
 private static void self(Tournament t,UUID actor,String participant){if(t.participants.stream().noneMatch(p->p.participantId().equals(participant)&&actor.equals(p.ownerUserId())))throw new AuthException("TEAM_MEMBER_NOT_OWNED",403);}
 public void create(Authentication auth,String id,Long revision,String name,String school,String participant){mutate(auth,id,revision,(t,actor)->{rosterOpen(t);self(t,actor,participant);require(name!=null&&!name.isBlank()&&name.length()<=60&&(school==null||school.length()<=80),"INVALID_TEAM_NAME");require(t.teams.teams().size()<10,"TEAM_LIMIT");require(t.teams.teams().stream().noneMatch(team->team.roster().contains(participant)),"TEAM_MEMBER_DUPLICATE");var teams=new ArrayList<>(t.teams.teams());var team=new TeamState.Team(UUID.randomUUID().toString(),name.trim(),school==null?"":school.trim(),actor,List.of(participant));teams.add(team);t.teams=new TeamState(teams,t.teams.fixtures());TournamentAudit.append(t,"TEAM_CREATED",actor,team.id(),null,null,null);});}
 public void join(Authentication auth,String id,Long revision,String teamId,String participant,boolean leave){mutate(auth,id,revision,(t,actor)->{rosterOpen(t);self(t,actor,participant);var teams=new ArrayList<>(t.teams.teams());int index=-1;for(int i=0;i<teams.size();i++)if(teams.get(i).id().equals(teamId))index=i;require(index>=0,"TEAM_NOT_FOUND");var team=teams.get(index);var roster=new ArrayList<>(team.roster());if(leave){require(roster.remove(participant),"TEAM_MEMBER_NOT_FOUND");}else{require(roster.size()<5,"TEAM_ROSTER_FULL");require(teams.stream().noneMatch(other->other.roster().contains(participant)),"TEAM_MEMBER_DUPLICATE");roster.add(participant);}if(roster.isEmpty())teams.remove(index);else {
 var members=t.participants.stream().filter(p->roster.contains(p.participantId())&&p.ownerUserId()!=null).toList();
 var captain=members.stream().anyMatch(p->team.captain().equals(p.ownerUserId()))?team.captain():roster.stream().map(member->members.stream().filter(p->p.participantId().equals(member)).findFirst().orElse(null)).filter(Objects::nonNull).findFirst().orElseThrow(()->new DemoRequestException("TEAM_ROSTER_INCOMPLETE")).ownerUserId();
 teams.set(index,new TeamState.Team(team.id(),team.name(),team.school(),captain,roster));
 }t.teams=new TeamState(teams,t.teams.fixtures());TournamentAudit.append(t,roster.isEmpty()?"TEAM_REMOVED":leave?"TEAM_MEMBER_LEFT":"TEAM_MEMBER_JOINED",actor,team.id(),null,participant,null);});}
 public void lineup(Authentication auth,String id,Long revision,String fixtureId,String teamId,List<String> lineup){mutate(auth,id,revision,(t,actor)->{require(Set.of(TournamentStatus.RUNNING,TournamentStatus.PAUSED,TournamentStatus.RECOVERY_REQUIRED).contains(t.status),"TOURNAMENT_LOCKED");var team=t.teams.teams().stream().filter(x->x.id().equals(teamId)).findFirst().orElseThrow(()->new DemoRequestException("TEAM_NOT_FOUND"));if(!actor.equals(team.captain())||t.participants.stream().noneMatch(p->team.roster().contains(p.participantId())&&actor.equals(p.ownerUserId())))throw new AuthException("TEAM_CAPTAIN_REQUIRED",403);require(lineup!=null&&lineup.size()==3&&new HashSet<>(lineup).size()==3&&team.roster().containsAll(lineup),"INVALID_TEAM_LINEUP");require(lineup.stream().allMatch(p->t.participants.stream().anyMatch(x->x.participantId().equals(p))),"INVALID_TEAM_LINEUP");var fixtures=new ArrayList<>(t.teams.fixtures());int index=-1;for(int i=0;i<fixtures.size();i++)if(fixtures.get(i).id().equals(fixtureId))index=i;require(index>=0,"TEAM_FIXTURE_NOT_FOUND");var f=fixtures.get(index);require(!f.locked(),"TEAM_LINEUP_LOCKED");require(f.lineupDeadline()==null||clock.instant().isBefore(f.lineupDeadline()),"TEAM_LINEUP_DEADLINE_PASSED");require(teamId.equals(f.teamA())||teamId.equals(f.teamB()),"TEAM_FIXTURE_FORBIDDEN");fixtures.set(index,new TeamState.Fixture(f.id(),f.round(),f.teamA(),f.teamB(),teamId.equals(f.teamA())?lineup:f.lineupA(),teamId.equals(f.teamB())?lineup:f.lineupB(),false,List.of(),f.lineupDeadline()));t.teams=new TeamState(t.teams.teams(),fixtures);TournamentAudit.append(t,"TEAM_LINEUP_SUBMITTED",actor,f.id(),teamId,null,null);});}
}
